package com.example

/**
 * Complete, distinct 20 cards for Science Sets 11 to 20 for Grade 10 and Grade 11.
 * Strictly guarantees distinct curriculum-aligned questions for Grade 10 vs Grade 11.
 */
object FlashcardBankScienceSetsPart2 {

  fun getScienceSet(setNum: Int, cardNum: Int, grade: String): CardContentTuple? {
    val c = cardNum.coerceIn(1, 20)
    val isGr11 = grade.contains("11")

    return when (setNum) {
      11 -> if (isGr11) scienceSet11Gr11[(c - 1) % scienceSet11Gr11.size] else scienceSet11[(c - 1) % scienceSet11.size]
      12 -> if (isGr11) scienceSet12Gr11[(c - 1) % scienceSet12Gr11.size] else scienceSet12[(c - 1) % scienceSet12.size]
      13 -> if (isGr11) scienceSet13Gr11[(c - 1) % scienceSet13Gr11.size] else scienceSet13[(c - 1) % scienceSet13.size]
      14 -> if (isGr11) scienceSet14Gr11[(c - 1) % scienceSet14Gr11.size] else scienceSet14[(c - 1) % scienceSet14.size]
      15 -> if (isGr11) scienceSet15Gr11[(c - 1) % scienceSet15Gr11.size] else scienceSet15[(c - 1) % scienceSet15.size]
      16 -> if (isGr11) scienceSet16Gr11[(c - 1) % scienceSet16Gr11.size] else scienceSet16[(c - 1) % scienceSet16.size]
      17 -> if (isGr11) scienceSet17Gr11[(c - 1) % scienceSet17Gr11.size] else scienceSet17[(c - 1) % scienceSet17.size]
      18 -> if (isGr11) scienceSet18Gr11[(c - 1) % scienceSet18Gr11.size] else scienceSet18[(c - 1) % scienceSet18.size]
      19 -> if (isGr11) scienceSet19Gr11[(c - 1) % scienceSet19Gr11.size] else scienceSet19[(c - 1) % scienceSet19.size]
      20 -> if (isGr11) scienceSet20Gr11[(c - 1) % scienceSet20Gr11.size] else scienceSet20[(c - 1) % scienceSet20.size]
      else -> null
    }
  }

  // =========================================================================
  // GRADE 10 SETS (11 TO 20)
  // =========================================================================

  // --- SET 11: තාපය, උෂ්ණත්වය & තාප සම්ප්‍රේෂණය (Grade 10) ---
  private val scienceSet11 = listOf(
    CardContentTuple("තාපය සහ උෂ්ණත්වය අතර මූලික වෙනස කුමක්ද?", "තාපය යනු අණුක චලිතය නිසා ඇතිවන ශක්ති විශේෂයකි (J); උෂ්ණත්වය යනු වස්තුවක රස්නය හෝ සීතල බව මනින මිනුමයි (K හෝ °C).", "තාපය වැඩි උෂ්ණත්වයේ සිට අඩු උෂ්ණත්වයට ගලා යයි.", "තාපය (ශක්තිය) vs උෂ්ණත්වය (මට්ටම)"),
    CardContentTuple("විශිෂ්ට තාප ධාරිතාව (Specific Heat Capacity - c) අර්ථ දක්වන්න.", "ද්‍රව්‍යයක 1 kg ස්කන්ධයක උෂ්ණත්වය 1 K (හෝ 1 °C) කින් වැඩි කිරීමට අවශ්‍ය තාප ප්‍රමාණයයි. ඒකකය J kg⁻¹ K⁻¹ වේ.", "Q = mcΔθ සූත්‍රය මගින් ගණනය කෙරේ.", "c = Q / (mΔθ)"),
